import nbformat as nbf
ROOT=Path(__file__).resolve().parents[2]
nb=nbf.v4.new_notebook(); nb.metadata={'kernelspec':{'display_name':'jup-venv','language':'python','name':'jup-venv'},'language_info':{'name':'python','version':'3.11'},'phase':10,'display_only':True}
