nb.cells=[md('# Phase 10 — KUB Fair Baseline Model Comparison\n\nDisplay-only finalized TRAIN/VAL results. **TEST was not accessed.** No cell trains or evaluates a model.'),code("from pathlib import Path\nimport json, pandas as pd\nfrom IPython.display import display, Image\nROOT=Path.cwd().resolve(); ROOT=ROOT.parent if ROOT.name=='notebooks' else ROOT\nT=ROOT/'reports/tables'; F=ROOT/'reports/figures/phase10_kub_comparison'; Q=ROOT/'reports/qualitative/phase10_kub_comparison'\ncomparison=pd.read_csv(T/'phase10_kub_model_comparison.csv')\nfairness=pd.read_csv(T/'phase10_kub_fairness_table.csv')\nassert len(comparison)==4\nprint('Governance: phase4_v2; TEST locked; TEST metrics NONE; external data not used')"),md('## Fairness and model parameters'),code("display(fairness)\ndisplay(comparison[['model','parameters','epochs_completed','best_epoch','physical_batch','effective_batch']])"),md('## Overall comparison and HD95'),code("display(comparison[['model','macro_dice','macro_iou','macro_precision','macro_recall','micro_dice','micro_iou','median_valid_hd95','mean_valid_hd95','empty_prediction_rate']])\ndisplay(Image(filename=str(F/'phase10_overall_dice_iou.png'),width=950))"),md('## FOV comparison'),code("display(comparison[['model','full_field_dice','roi_crop_dice']])\ndisplay(Image(filename=str(F/'phase10_fov_performance.png'),width=950))"),md('## Category comparison'),code("display(Image(filename=str(F/'phase10_category_dice.png'),width=950))"),md('## Frozen original-space size comparison'),code("display(comparison[['model','tiny_object_recall','small_object_recall','medium_object_recall','large_object_recall']])\ndisplay(Image(filename=str(F/'phase10_size_recall.png'),width=950))"),md('## Evaluation-space object metrics'),code("display(comparison[['model','object_recall','missed_object_rate','fp_components_per_image']])\ndisplay(Image(filename=str(F/'phase10_object_recall_vs_fp.png'),width=850))"),md('## FULL_FIELD multi-component comparison'),code("display(pd.read_csv(T/'phase10_kub_multicomponent_comparison.csv'))"),md('## Efficiency and learning curves'),code("display(comparison[['model','parameters','training_wall_time','mean_epoch_time','peak_gpu_allocated','peak_gpu_reserved']])\ndisplay(Image(filename=str(F/'phase10_parameters_vs_dice.png'),width=850))\ndisplay(Image(filename=str(F/'phase10_training_efficiency.png'),width=950))\ndisplay(Image(filename=str(F/'phase10_val_dice_learning_curves.png'),width=950))"),md('## Common-sample qualitative comparison'),code("display(Image(filename=str(Q/'phase10_common_sample_comparison.png'),width=1200))"),md('## Deterministic failure comparison'),code("display(pd.read_csv(T/'phase10_kub_failure_comparison.csv'))\ndisplay(Image(filename=str(Q/'phase10_failure_comparison.png'),width=1000))"),md('## Limitations\n\nSingle seed (42), one internal validation split, and descriptive comparisons only. No formal significance or causality claims are made. Original-space `kub_size_v1` and 512×512 evaluation-space object counts are explicitly distinct.'),md('## Phase control\n\n**TEST NOT ACCESSED. Phase 10 complete. STOP. Phase 11 requires explicit authorization.**')]
out=ROOT/'notebooks/08_kub_baseline_comparison.ipynb'; out.write_text(nbf.writes(nb),encoding='utf-8'); print(out)
